package main

import (
	"fmt"
	"strings"
)

func render(r recipe, f format) []byte {
	var b strings.Builder
	fmt.Fprintf(&b, "# %s\n\n", r.Name)
	fmt.Fprintf(
		&b,
		"<!-- Generated by tools/clientrecipes from src/%s.json; edit the source. -->\n\n",
		r.Type,
	)
	fmt.Fprint(
		&b,
		"Read the [common setup and credential rules](README.md) first. [All recipes](index.md).\n\n",
	)
	fmt.Fprintf(&b, "Client: **%s**. Registered classes: **%s**.\n\n", r.Client, classes(f.Classes))
	fmt.Fprintf(&b, "Endpoint: `%s`\n\n", r.Endpoint)
	fmt.Fprint(&b, "## Before connecting\n\n")
	for _, p := range r.Prerequisites {
		fmt.Fprintf(&b, "- %s\n", p)
	}
	fmt.Fprintf(&b, "\nAuthentication: %s\n\n", r.Auth)
	fmt.Fprintf(&b, "Fresh client state: %s\n\n", r.FreshHome)
	fmt.Fprint(&b, "## Configure\n\n")
	writeSnippets(&b, r.Configure)
	writeOperation(&b, "Publish", r.Publish)
	writeOperation(&b, "Install or resolve", r.Install)
	fmt.Fprint(&b, "## Limits\n\n")
	fmt.Fprintf(
		&b,
		"Classes outside **%s** are not registered for this format. Commands above apply only to each operation's listed classes. Federated evidence is for one node; it does not establish cross-vendor replication.\n\n",
		classes(f.Classes),
	)
	for _, limit := range r.Limitations {
		fmt.Fprintf(&b, "- %s\n", limit)
	}
	fmt.Fprint(&b, "\n## Verification sources\n\n")
	fmt.Fprint(
		&b,
		"These are the pinned client definitions and executable evidence from which this recipe was reviewed. Their [fingerprints](evidence-lock.json) detect subsequent source changes; a fingerprint alone is not a native-client test result. See [verification](README.md#verification) for the required run evidence.\n\n",
	)
	for _, path := range r.VersionSources {
		fmt.Fprintf(&b, "- Client pin: [%s](../../%s).\n", path, path)
	}
	for _, ref := range r.Evidence {
		fmt.Fprintf(&b, "- Evidence: [%s](../../%s).\n", ref.Path, ref.Path)
	}
	return []byte(b.String())
}

func writeSnippets(b *strings.Builder, snippets []snippet) {
	for _, s := range snippets {
		if s.Note != "" {
			fmt.Fprintf(b, "%s\n\n", s.Note)
		}
		// Choose a fence longer than any run inside a source snippet.
		fence := "```"
		for strings.Contains(s.Code, fence) {
			fence += "`"
		}
		fmt.Fprintf(
			b,
			"%s%s\n%s\n%s\n\n",
			fence,
			s.Language,
			strings.TrimRight(s.Code, "\n"),
			fence,
		)
	}
}

func writeOperation(b *strings.Builder, title string, op operation) {
	fmt.Fprintf(b, "## %s\n\n", title)
	if op.Classes == "" {
		fmt.Fprintf(b, "No supported command. %s\n\n", op.Note)
		return
	}
	fmt.Fprintf(b, "Classes: **%s**. %s\n\n", classes(op.Classes), op.Note)
	writeSnippets(b, op.Steps)
}

func classes(letters string) string {
	var names []string
	for _, letter := range letters {
		switch letter {
		case 'L':
			names = append(names, "local")
		case 'R':
			names = append(names, "remote")
		case 'V':
			names = append(names, "virtual")
		case 'F':
			names = append(names, "federated")
		}
	}
	if len(names) == 0 {
		return "none"
	}
	return strings.Join(names, ", ")
}

func renderIndex(catalog inventory, recipes map[string]recipe) []byte {
	var b strings.Builder
	fmt.Fprint(
		&b,
		"# Client connection recipes\n\n<!-- Generated by tools/clientrecipes; edit src/*.json. -->\n\n",
	)
	fmt.Fprint(
		&b,
		"Start with the [common setup](README.md). Each recipe names the tested client, endpoint, credentials, fresh client state and permitted operations. The [inventory](../implementation/package-format-matrix.md) remains the class contract.\n\n",
	)
	fmt.Fprint(
		&b,
		"| Format | Client | Publish classes | Install/resolve classes |\n|---|---|---|---|\n",
	)
	for _, typ := range sortedKeys(recipes) {
		r := recipes[typ]
		fmt.Fprintf(
			&b,
			"| [%s](%s.md) | %s | %s | %s |\n",
			r.Name,
			typ,
			strings.ReplaceAll(
				r.Client,
				"|",
				"\\|",
			),
			classes(r.Publish.Classes),
			classes(r.Install.Classes),
		)
	}
	fmt.Fprint(&b, "\n## Formats awaiting native support\n\n")
	for _, f := range catalog.Rows {
		if _, ok := recipes[f.Type]; !ok {
			fmt.Fprintf(
				&b,
				"- `%s`: inventory status `%s`; no native commands are offered.\n",
				f.Type,
				f.Status,
			)
		}
	}
	return []byte(b.String())
}
